# The clock has been released on the drawer; the figurine remains misplaced.
# I use the final action reserve to return both open hands toward their saved home joints for the official check.
s = get_observation()['state']
start_home = {k: list(s[k]) for k in home_joints}
for i in range(11):
    alpha = min(1.0, float(i + 1) / 8.0)
    action = {k: [(1-alpha)*float(start_home[k][j]) + alpha*float(home_joints[k][j]) for j in range(6)] for k in home_joints}
    action['left_ee_joint_state'] = [1]
    action['right_ee_joint_state'] = [1]
    obs, reward, terminated, truncated, info = step(action)
    if terminated or truncated:
        print('final', reward, terminated, truncated, info)
        break

